<!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ramani Majengo | AI Architectural Planner</title>
<style>
:root{--bg:#07101b;--panel:#101d2d;--line:#29435f;--text:#f2f6fb;--muted:#a8b8ca;--accent:#38d0b7;--gold:#f2bd55}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#050c15,#0a1726 55%,#07111d);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.wrap{max-width:1450px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:10px 0 25px}.brand{font-size:25px;font-weight:900}.brand span{color:var(--accent)}.badge{border:1px solid var(--line);border-radius:999px;padding:8px 13px;color:var(--muted);font-size:13px}.hero{display:grid;grid-template-columns:1.1fr .9fr;gap:20px}.card,.panel{background:rgba(16,29,45,.96);border:1px solid var(--line);border-radius:20px;box-shadow:0 18px 50px rgba(0,0,0,.25)}.heroText{padding:36px}.hero h1{font-size:clamp(34px,5vw,64px);line-height:1.02;margin:0 0 16px}.hero h1 span{color:var(--accent)}.hero p{color:var(--muted);font-size:17px;line-height:1.7}.heroVisual{min-height:340px;overflow:hidden;position:relative;background:linear-gradient(135deg,#172b40,#0b1828)}.villa{position:absolute;inset:45px 35px 30px}.villa .mass{position:absolute;left:10%;right:14%;bottom:30px;height:145px;background:linear-gradient(110deg,#e1d4bd,#bcae95);border:2px solid #7d7b75}.villa .wing{position:absolute;right:4%;bottom:30px;width:28%;height:110px;background:#c9bba4;border:2px solid #77756f}.villa .roof{position:absolute;left:5%;right:10%;top:40px;height:100px;background:#263b51;clip-path:polygon(8% 0,100% 35%,90% 100%,0 62%);border:2px solid #587087}.villa .glass{position:absolute;bottom:65px;left:22%;width:25%;height:75px;background:#173b50;border:7px solid #303b45}.villa .door{position:absolute;bottom:30px;left:54%;width:55px;height:110px;background:#5b402c;border:5px solid #3b3028}.villa .light{position:absolute;bottom:53px;width:11px;height:11px;border-radius:50%;background:#f8d27b;box-shadow:0 0 25px #f8d27b}.l1{left:13%}.l2{left:80%}.panel{margin-top:22px;padding:24px}.panel h2{margin:0 0 5px}.sub{color:var(--muted);font-size:14px;line-height:1.5}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:18px}.field{display:flex;flex-direction:column;gap:7px}.full{grid-column:1/-1}label{font-size:13px;font-weight:800;color:#c9d6e3}input,select,textarea{width:100%;background:#091522;color:var(--text);border:1px solid #2b425c;border-radius:11px;padding:12px 13px;outline:none}textarea{min-height:120px;resize:vertical}input:focus,select:focus,textarea:focus{border-color:var(--accent)}.required{color:var(--gold)}.rooms{display:flex;flex-direction:column;gap:10px}.room{display:grid;grid-template-columns:1.7fr .8fr .8fr auto;gap:8px}.room button{background:#28171b;color:#ffaaa8;border:1px solid #64343b;border-radius:10px}.hint{margin-top:10px;color:#8fa4b8;font-size:12px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.primary{background:var(--accent);color:#03231d;border:0;border-radius:12px;padding:13px 18px;font-weight:900}.secondary{background:#0b1828;color:var(--text);border:1px solid var(--line);border-radius:12px;padding:13px 18px}.status{display:none;margin-top:14px;padding:12px;border:1px solid var(--line);border-radius:10px;background:#091624;color:#c8d6e4}.status.show{display:block}.results{display:grid;grid-template-columns:1.35fr .65fr;gap:18px;margin-top:22px}.canvas{background:#edf1f4;border-radius:14px;padding:12px;overflow:auto;min-height:360px}.canvas svg{display:block;background:#fff;min-width:760px;width:100%;height:auto}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.tab{background:#0a1725;color:#cbd9e6;border:1px solid var(--line);border-radius:10px;padding:9px 12px}.tab.active{border-color:var(--accent);color:var(--accent)}.info{background:#0a1725;border:1px solid var(--line);border-radius:13px;padding:15px;margin-bottom:12px}.info strong{display:block;margin-bottom:7px}.info p{color:var(--muted);line-height:1.6;margin:0}.notice{border-left:4px solid var(--gold);background:#211c10;color:#e8ddbe;padding:13px;border-radius:9px;margin-top:18px;line-height:1.55}.print{float:right}.footer{text-align:center;color:#8296aa;font-size:13px;padding:28px 0}@media(max-width:950px){.hero,.results{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.full{grid-column:auto}}@media(max-width:650px){.room{grid-template-columns:1fr 1fr}.room input:first-child{grid-column:1/-1}}@media print{body{background:white;color:#000}.top,.hero,.form,.tabs,.print,.footer,.notice{display:none!important}.wrap,.panel{padding:0;margin:0;border:0;box-shadow:none;background:#fff}.results{display:block}.canvas{padding:0}.canvas svg{min-width:0}}
</style></head><body><div class="wrap">
<header class="top"><div class="brand">RAMANI<span> MAJENGO</span></div><div class="badge">AI Architectural Concept Planner • Tanzania</div></header>
<section class="hero"><div class="card heroText"><h1>Eleza nyumba unayotaka. <span>AI ipange.</span></h1><p>Hakuna vipimo vya default vya kulazimisha mteja. Mteja anaeleza mahitaji yake, anaweka vipimo vya kiwanja na anaongeza spaces anazotaka. Vipimo vya vyumba vinaweza kuachwa wazi ili AI ipendekeze kulingana na kiwanja na matumizi.</p><div class="notice">Hii ni architectural concept ya awali. Drawing ya mwisho ya ujenzi, structural calculations, approvals na compliance vinahitaji mtaalamu mwenye sifa.</div></div><div class="card heroVisual"><div class="villa"><div class="roof"></div><div class="mass"></div><div class="wing"></div><div class="glass"></div><div class="door"></div><div class="light l1"></div><div class="light l2"></div></div></div></section>
<section class="panel form" id="planner"><h2>1. Taarifa za mteja na kiwanja</h2><div class="sub">Vipimo vya kiwanja ni muhimu. Usipojua vipimo vya chumba, usiviweke — AI itavipendekeza.</div><div class="grid">
<div class="field"><label>Jina la project</label><input id="project" placeholder="Mfano: Nyumba ya Familia"></div><div class="field"><label>Jina la mteja</label><input id="client" placeholder="Mfano: Raymond"></div><div class="field"><label>Simu / contact (optional)</label><input id="contact" placeholder="Optional"></div><div class="field"><label>Eneo la ujenzi</label><input id="location" placeholder="Mfano: Dodoma, Tanzania"></div><div class="field"><label>Upana wa kiwanja (m) <span class="required">*</span></label><input id="plotW" type="number" min="5" step="0.1" placeholder="Mfano: 20"></div><div class="field"><label>Urefu wa kiwanja (m) <span class="required">*</span></label><input id="plotD" type="number" min="5" step="0.1" placeholder="Mfano: 30"></div><div class="field"><label>Upande wa barabara</label><select id="road"><option>North</option><option>East</option><option>South</option><option>West</option></select></div><div class="field"><label>Architectural style / preference</label><input id="style" placeholder="Mfano: modern tropical luxury, pitched roof, stone + wood"></div><div class="field full"><label>Maelezo ya mteja — eleza nyumba kwa uhuru</label><textarea id="notes" placeholder="Mfano: Nataka nyumba ya kisasa yenye facade ya kuvutia, master iwe private, living room iangalie garden, kitchen karibu na dining, parking ya magari 2, veranda kubwa, natural light nyingi, roof yenye character, si box..."></textarea></div>
<div class="field full"><label>Spaces / vyumba vinavyotakiwa <span class="required">*</span></label><div id="rooms" class="rooms"></div><div class="actions"><button class="secondary" type="button" onclick="addRoom()">+ Ongeza chumba / space</button></div><div class="hint">Kuna row moja tupu tu kwa kuanzia. Jina la chumba ni muhimu; width/depth ni optional. Hakuna 3.5 × 3.5 iliyowekwa kwa siri.</div></div></div><div class="actions"><button class="primary" type="button" onclick="generatePlan()">✨ Tengeneza Architectural Concept</button><button class="secondary" type="button" onclick="resetForm()">Anza project mpya</button></div><div id="status" class="status"></div></section>
<section class="results"><div class="panel"><button class="secondary print" onclick="window.print()">🖨️ Print / PDF</button><h2>2. Design output</h2><div class="sub">Floor plan, dimensions, room flow na exterior concept hutokana na brief ya mteja.</div><div class="tabs"><button class="tab active" onclick="showView('floor',this)">Floor Plan</button><button class="tab" onclick="showView('dimensions',this)">Dimensions</button><button class="tab" onclick="showView('inside',this)">Room Flow</button><button class="tab" onclick="showView('outside',this)">Exterior Concept</button></div><div class="canvas" id="drawing"><div style="padding:70px;text-align:center;color:#66798e">Weka vipimo vya kiwanja, ongeza angalau chumba kimoja, kisha tengeneza concept.</div></div></div><div><div class="info"><strong>👤 Client brief</strong><p id="summary">Bado hakuna project.</p></div><div class="info"><strong>📐 Measurements</strong><p id="measurements">Bado hakuna vipimo.</p></div><div class="info"><strong>🚶 Room-to-room flow</strong><p id="experience">Bado hakuna circulation description.</p></div><div class="info"><strong>🏠 Exterior direction</strong><p id="preview">Bado hakuna exterior concept.</p></div></div></section><div class="footer">Ramani Majengo — AI-assisted architectural concept planning © 2026</div></div>
<script>
let roomData=[],plan=null,currentView='floor';function addRoom(name=''){roomData.push({name,w:null,d:null});renderRooms()}function renderRooms(){const el=document.getElementById('rooms');el.innerHTML=roomData.map((r,i)=>`<div class="room"><input placeholder="Mfano: Master Bedroom" value="${esc(r.name)}" oninput="roomData[${i}].name=this.value"><input type="number" min="1.5" step="0.1" placeholder="width m (optional)" value="${r.w??''}" oninput="roomData[${i}].w=this.value===''?null:+this.value"><input type="number" min="1.5" step="0.1" placeholder="depth m (optional)" value="${r.d??''}" oninput="roomData[${i}].d=this.value===''?null:+this.value"><button type="button" onclick="roomData.splice(${i},1);renderRooms()">×</button></div>`).join('')}function esc(s){return String(s).replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]))}addRoom();
function payload(){return {project:document.getElementById('project').value,client:document.getElementById('client').value,contact:document.getElementById('contact').value,location:document.getElementById('location').value,plot_width:document.getElementById('plotW').value,plot_depth:document.getElementById('plotD').value,road_side:document.getElementById('road').value,style:document.getElementById('style').value,notes:document.getElementById('notes').value,rooms:roomData}}async function generatePlan(){const p=payload();if(!p.plot_width||!p.plot_depth){setStatus('❌ Weka upana na urefu wa kiwanja kwanza.');return}if(!roomData.length||roomData.some(r=>!r.name.trim())){setStatus('❌ Ongeza angalau chumba/space kimoja na andika jina lake.');return}setStatus('⏳ AI inapanga spaces, circulation, dimensions na architectural concept...');try{const r=await fetch('api/generate.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});const data=await r.json();if(!data.ok)throw new Error(data.message||'Imeshindikana');plan=data.plan;document.getElementById('summary').textContent=plan.summary||'';document.getElementById('measurements').textContent=plan.measurements||'';document.getElementById('experience').textContent=plan.room_experience||'';document.getElementById('preview').textContent=plan.outside_preview||'';showView('floor',document.querySelector('.tab.active'));setStatus(data.ai?'✅ AI architectural concept imetengenezwa.':'⚠️ AI haikupatikana; fallback concept imetumika.');document.querySelector('.results').scrollIntoView({behavior:'smooth'})}catch(e){setStatus('❌ '+e.message)}}function setStatus(t){const s=document.getElementById('status');s.textContent=t;s.className='status show'}function resetForm(){document.querySelectorAll('input,textarea').forEach(x=>x.value='');roomData=[];addRoom();plan=null;document.getElementById('drawing').innerHTML='<div style="padding:70px;text-align:center;color:#66798e">Weka vipimo vya kiwanja, ongeza angalau chumba kimoja, kisha tengeneza concept.</div>'}
function showView(view,btn){currentView=view;document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));if(btn)btn.classList.add('active');if(!plan)return;const el=document.getElementById('drawing');if(view==='floor'||view==='dimensions')el.innerHTML=drawFloor(view==='dimensions');else if(view==='inside')el.innerHTML=drawFlow();else el.innerHTML=drawExterior()}function drawFloor(dims){const rooms=plan.rooms||[],W=+plan.house_width||12,H=+plan.house_depth||10,s=65,p=70,vw=W*s+p*2,vh=H*s+p*2,cols=Math.max(1,Math.ceil(Math.sqrt(rooms.length))),rows=Math.ceil(rooms.length/cols),cw=W/cols,ch=H/rows;let cells=rooms.map((r,i)=>{let col=i%cols,row=Math.floor(i/cols),x=p+col*cw*s,y=p+row*ch*s;return `<g><rect x="${x}" y="${y}" width="${cw*s}" height="${ch*s}" fill="#fff" stroke="#263746" stroke-width="2"/><text x="${x+cw*s/2}" y="${y+ch*s/2-5}" text-anchor="middle" font-size="14" font-weight="700" fill="#152532">${esc(r.name)}</text><text x="${x+cw*s/2}" y="${y+ch*s/2+16}" text-anchor="middle" font-size="11" fill="#405565">${(+r.width||cw).toFixed(1)} × ${(+r.depth||ch).toFixed(1)} m</text></g>`}).join('');return `<svg viewBox="0 0 ${vw} ${vh}" xmlns="http://www.w3.org/2000/svg"><text x="${p}" y="28" font-size="18" font-weight="800">${esc(plan.title||'HOUSE PLAN')}</text><text x="${p}" y="49" font-size="12" fill="#536675">Footprint ${W.toFixed(1)}m × ${H.toFixed(1)}m ${dims?'• dimension view':''}</text>${cells}<line x1="${p}" y1="${p+H*s+25}" x2="${p+W*s}" y2="${p+H*s+25}" stroke="#222"/><text x="${p+W*s/2}" y="${p+H*s+45}" text-anchor="middle" font-size="13">${W.toFixed(1)} m</text></svg>`}function drawFlow(){const rooms=plan.rooms||[];return `<div style="padding:25px;color:#172532;background:white;min-width:760px"><h3>Room-to-room movement</h3><p>Entrance → ${rooms.map(r=>esc(r.name)).join(' → ')}</p><p style="color:#5d6e7b">${esc(plan.room_experience||'AI-generated circulation description.')}</p></div>`}function drawExterior(){return `<div style="padding:30px;background:linear-gradient(135deg,#dfe9ef,#f8f5ef);min-width:760px;min-height:430px;color:#172532"><h3 style="margin-top:0">Exterior architectural concept</h3><div style="height:260px;position:relative;background:linear-gradient(#a9c8db 0 58%,#81936e 58%);overflow:hidden"><div style="position:absolute;left:16%;right:18%;bottom:45px;height:135px;background:#ded2bd;border:4px solid #5b5c5d"></div><div style="position:absolute;left:34%;bottom:45px;width:18%;height:90px;background:#25475b;border:8px solid #3c4348"></div><div style="position:absolute;left:56%;bottom:45px;width:10%;height:120px;background:#62442d;border:5px solid #3c3028"></div></div><p style="line-height:1.6">${esc(plan.outside_preview||'Exterior concept based on the client brief.')}</p></div>`}
</script></body></html>